} catch (error) {
  summary.skipped.push({ orderId: order.id, error });
  // 決済サービス全体の障害なら、残りに問い合わせても同じ結果になる
  if (isServiceOutage(error)) break;
}

function isServiceOutage(e: unknown): boolean {
  if (e instanceof PaymentTimeoutError) return true;
  return e instanceof PaymentUnavailableError &&
    (e.status === 0 || e.status === 429 || e.status >= 500);
}
